import{_ as t,o as s,c as n,a4 as e}from"./chunks/framework.BRzJ4ijD.js";const h=JSON.parse('{"title":"量子计算卷 · 用量子比特重新定义\\"计算\\"","description":"","frontmatter":{},"headers":[],"relativePath":"quantum/index.md","filePath":"quantum/README.md","lastUpdated":1788475713000}'),o={name:"quantum/index.md"};function r(i,a,l,u,c,d){return s(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="量子计算卷-·-用量子比特重新定义-计算" tabindex="-1">量子计算卷 · 用量子比特重新定义&quot;计算&quot; <a class="header-anchor" href="#量子计算卷-·-用量子比特重新定义-计算" aria-label="Permalink to &quot;量子计算卷 · 用量子比特重新定义&quot;计算&quot;&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>经典计算机用比特（0 或 1）计算；<strong>量子计算机用量子比特（qubit）</strong>——它可以处于 0 和 1 的<strong>叠加态</strong>，多个 qubit 之间存在<strong>纠缠</strong>。量子计算的目标：对某些特定问题（大数分解、无序搜索、量子模拟）提供<strong>指数级/平方级加速</strong>。这一卷讲透量子计算的三块基础：物理基础（Dirac 记号 / qubit / 门 / 测量）、核心算法（Deutsch-Jozsa / Grover / Shor）、以及落地最大的障碍（量子纠错 / surface code）。</p><h2 id="思想链" tabindex="-1">思想链 <a class="header-anchor" href="#思想链" aria-label="Permalink to &quot;思想链&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[经典计算: bit = 0 或 1, 一次算一个状态]</span></span>
<span class="line"><span>  └─&gt; qubit = α|0⟩ + β|1⟩ (叠加态, 测量才坍缩)</span></span>
<span class="line"><span>        └─&gt; 量子门 = 旋转矩阵 (酉变换, 可逆)</span></span>
<span class="line"><span>              └─&gt; 纠缠: 两个 qubit 关联, 测量一个立即影响另一个</span></span>
<span class="line"><span>                    └─&gt; 量子并行: n qubit 叠加 2ⁿ 个状态同时演化</span></span>
<span class="line"><span>                          └─&gt; 但测量坍缩 → 只能&quot;一次读一个&quot; → 算法要巧妙</span></span>
<span class="line"><span>                                └─&gt; Deutsch-Jozsa: 判定函数是常量还是平衡 (1 次查询)</span></span>
<span class="line"><span>                                      └─&gt; Grover: 无序搜索 √N (经典 N)</span></span>
<span class="line"><span>                                            └─&gt; Shor: 大数分解多项式时间 (经典指数)</span></span>
<span class="line"><span>                                                  └─&gt; 但物理噪声 → 需要纠错</span></span>
<span class="line"><span>                                                        └─&gt; surface code: 用大量物理 qubit 编码 1 个逻辑 qubit</span></span>
<span class="line"><span>                                                              └─&gt; 现在: ~100 逻辑 qubit 门槛, 距 RSA 威胁仍远</span></span></code></pre></div><h2 id="你将带走什么" tabindex="-1">你将带走什么 <a class="header-anchor" href="#你将带走什么" aria-label="Permalink to &quot;你将带走什么&quot;">​</a></h2><p>读完应能：</p><ol><li>用 Dirac 记号（<code>|0⟩ |1⟩ |+⟩</code>）写 qubit 状态，理解叠加与测量坍缩。</li><li>知道量子门是酉变换（<code>U†U = I</code>），会写常见门（X/H/CNOT）矩阵。</li><li>理解纠缠为什么是量子计算的核心资源。</li><li>理解 Deutsch-Jozsa、Grover、Shor 三个算法&quot;快在哪&quot;，以及为什么 Shor 威胁 RSA。</li><li>理解量子纠错的本质（用冗余逻辑比特 + 测量纠错），知道 surface code 为什么主流。</li><li>知道当前量子计算的实际状态（logical qubit 时代、Y2Q 估计），不迷信炒作。</li></ol><h2 id="章节结构" tabindex="-1">章节结构 <a class="header-anchor" href="#章节结构" aria-label="Permalink to &quot;章节结构&quot;">​</a></h2><ul><li><a href="./">开篇: 用量子比特重新定义&quot;计算&quot;</a> ← 当前</li><li><a href="./basics">1. 量子计算基础: Dirac 记号 / qubit / 量子门 / 测量</a></li><li><a href="./algorithms">2. 量子算法: Deutsch-Jozsa / Grover / Shor</a></li><li><a href="./error-correction">3. 量子纠错: 逻辑 qubit / surface code / 现实挑战</a></li></ul><h2 id="与其余部分的接口" tabindex="-1">与其余部分的接口 <a class="header-anchor" href="#与其余部分的接口" aria-label="Permalink to &quot;与其余部分的接口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>本卷</th><th>接口</th></tr></thead><tbody><tr><td>基础（qubit/门/测量）</td><td>数学 §线代（复数/矩阵/酉/张量积）、组成原理（门电路类比）</td></tr><tr><td>Shor 算法</td><td>数学 §离散数学（数论/模运算）、密码学 §RSA（为什么 RSA 怕 Shor）</td></tr><tr><td>Grover 算法</td><td>DSA §搜索、数学 §概率</td></tr><tr><td>量子纠错</td><td>信息论 §编码（经典纠错类比）、密码学 §量子安全</td></tr></tbody></table><h2 id="这卷不是什么" tabindex="-1">这卷不是什么 <a class="header-anchor" href="#这卷不是什么" aria-label="Permalink to &quot;这卷不是什么&quot;">​</a></h2><ul><li><strong>不是</strong>完整量子物理课（不讲薛定谔方程推导、具体超导/离子阱实现）。</li><li><strong>不是</strong>量子力学世界观科普（聚焦&quot;计算&quot;模型，不谈哲学）。</li><li><strong>不是</strong>说经典计算要被取代——量子只对<strong>特定问题</strong>有优势。</li></ul><h2 id="现状提醒" tabindex="-1">现状提醒 <a class="header-anchor" href="#现状提醒" aria-label="Permalink to &quot;现状提醒&quot;">​</a></h2><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>截至 2026 年：量子纠错进入&quot;logical qubit&quot;时代（~100 逻辑 qubit 级），但 <strong>Shor 要破解 RSA-2048 需要 100 万-1000 万物理 qubit</strong>，业内 &quot;Y2Q&quot; 估计仍在 10-30 年。量子计算是<strong>真实但长期</strong>的方向——值得懂原理，别信&quot;明年就破解&quot;。</p></div><hr><p>下一篇: <a href="./basics">1. 量子计算基础: Dirac 记号 / qubit / 量子门 / 测量</a>.</p>`,18)])])}const q=t(o,[["render",r]]);export{h as __pageData,q as default};
